insert into public.journal_posts (slug, title, category, published_on, read_minutes, dek, body) values ($q$sadequain-calligraphy-as-painting$q$, $q$Sadequain: When Calligraphy Became Painting$q$, $q$Artists$q$, $q$2026-10-12$q$::date, 1, $q$How a painter from Amroha turned the written word into monumental modern art, and why his work still matters for Pakistani artists.$q$, $q$[{"p":"Syed Sadequain Ahmed Naqvi (1930–1987) is often remembered as the artist who brought calligraphy out of the manuscript and onto the wall. Born in Amroha and later based in Karachi, he worked across painting, murals and poetry."},{"h":"From figure to letter"},{"p":"In his early career Sadequain was known for expressive figurative work. Over time the letter took over: Quranic verses and poetry became the structure of his compositions, with strokes that behaved like both script and drawing."},{"quote":"He treated the letter not as decoration but as a living form."},{"h":"Why he matters today"},{"p":"His murals, including the celebrated ceiling at Frere Hall in Karachi, showed that calligraphy could hold its own at the scale of public art. For artists working today, he remains proof that tradition and modernity are not opposites."}]$q$::jsonb) on conflict (slug) do nothing;
insert into public.journal_posts (slug, title, category, published_on, read_minutes, dek, body) values ($q$nastaliq-the-hanging-script$q$, $q$Nastaliq: The Hanging Script$q$, $q$Art styles$q$, $q$2026-09-02$q$::date, 1, $q$A short history of the script that carries Urdu and Persian poetry — its origins, its rhythm, and what makes it so hard to master.$q$, $q$[{"p":"Nastaliq emerged in Iran in the fourteenth and fifteenth centuries and is traditionally associated with the calligrapher Mir Ali Tabrizi. Its name is often explained as a blend of Naskh and Taliq."},{"h":"A script that slopes"},{"p":"Unlike scripts that sit on a flat baseline, Nastaliq words descend diagonally from right to left. This gives lines of poetry their characteristic hanging, flowing quality."},{"h":"Nastaliq in the subcontinent"},{"p":"Under the Mughals the script flourished, and it became the standard hand for Urdu. Even in the age of digital type, the craft of hand-written Nastaliq is still studied and treasured in Pakistan."}]$q$::jsonb) on conflict (slug) do nothing;
insert into public.journal_posts (slug, title, category, published_on, read_minutes, dek, body) values ($q$ibn-muqla-proportioned-script$q$, $q$Ibn Muqla and the Science of Proportion$q$, $q$Artists$q$, $q$2026-07-18$q$::date, 1, $q$The tenth-century vizier who gave Arabic calligraphy its rules — the alif, the rhombic dot, and a system still taught today.$q$, $q$[{"p":"Abu Ali Muhammad ibn Muqla (c. 885–940) served as a vizier in Abbasid Baghdad. His lasting legacy, however, is a method: al-khatt al-mansub, the proportioned script."},{"h":"Measuring with the pen"},{"p":"Ibn Muqla used the rhombic dot made by the reed pen as a unit of measure. The height of the alif was set in dots, and every other letter was sized in relation to it."},{"quote":"Proportion turned beautiful writing into a teachable discipline."},{"p":"This system is the reason a student today can learn Naskh or Thuluth step by step. In my own classes, the dot and the alif are still the first lesson."}]$q$::jsonb) on conflict (slug) do nothing;
